return (
    ts.isFunctionDeclaration(node) ||
    ts.isFunctionExpression(node) ||
    ts.isArrowFunction(node) ||
    ts.isMethodDeclaration(node) ||
    ts.isConstructorDeclaration(node) ||
    ts.isGetAccessorDeclaration(node) ||
    ts.isSetAccessorDeclaration(node)
  );

const visit = (node: ts.Node): void => {
    if (ts.isFunctionDeclaration(node) && node.name && SHADOW_NAMES.has(node.name.text)) {
      out.add(node.name.text);
    } else if (
      ts.isVariableDeclaration(node) &&
      ts.isIdentifier(node.name) &&
      SHADOW_NAMES.has(node.name.text) &&
      node.initializer &&
      (ts.isArrowFunction(node.initializer) || ts.isFunctionExpression(node.initializer))
    ) {
      out.add(node.name.text);
    }
    ts.forEachChild(node, visit);
  };

return {
    id: edgeId(src, dst, rel),
    src,
    dst,
    rel,
    method: 'static',
    provenance: 'EXTRACTED',
    confidence: 1,
    evidence: { by: 'lang:typescript/http-client', snippet },
  };

const visit = (node: ts.Node): void => {
    if (ts.isCallExpression(node)) {
      const match = matchHttpCall(node, lineOf, shadowed);
      if (match) {
        const { method, routePath, framework, callLine, callEnd } = match;
        const callId = ctx.idFor('http-call', {
          httpMethod: method,
          routePath,
          file: path,
          line: callLine,
        });
        // De-dupe by id: an identical `fetch('/x')` emitted twice on the same line keeps one node.
        if (!nodes.some((n) => n.id === callId)) {
          nodes.push({
            id: callId,
            kind: 'http-call',
            name: `${method} ${routePath}`,
            httpMethod: method,
            routePath,
            framework,
            file: path,
            span: { start: callLine, end: callEnd },
            lang,
            hash: ctx.hash(`${path}:http-call:${method}:${routePath}:${callLine}`),
          });
        }
        const callerId = enclosingCallableId(node, symbolByNode);
        if (callerId) {
          edges.push(edge(callerId, callId, 'calls', `${method} ${routePath}`));
        }
      }
    }
    ts.forEachChild(node, visit);
  };

const callId = ctx.idFor('http-call', {
          httpMethod: method,
          routePath,
          file: path,
          line: callLine,
        });

const allMatches = nodes
      .filter((node) => searchText(node).some((value) => value.includes(query)))
      .sort((a, b) => {
        return (
          searchRank(a, query) - searchRank(b, query) ||
          (b.importance || 0) - (a.importance || 0) ||
          String(a.qualified || a.label || a.id).localeCompare(
            String(b.qualified || b.label || b.id),
          ) ||
          a.id.localeCompare(b.id)
        );
      });

return {
      query,
      matchIds,
      contextIds,
      nodeIds,
      edgeIndexes: edgeIndexesForNodeIds(nodeIds, edges, indexes),
      totalMatches: allMatches.length,
    };

return {
      allMemberIds,
      filteredMemberIds,
      coreIds,
      contextIds,
      nodeIds,
      edgeIndexes: edgeIndexesForNodeIds(nodeIds, edges, indexes),
      totalCore: filteredMemberIds.length,
      hiddenCore: Math.max(0, filteredMemberIds.length - coreIds.length),
    };

edges.forEach((edge, index) => {
      if (incidentByNode[edge.src]) incidentByNode[edge.src].push(index);
      if (incidentByNode[edge.dst]) incidentByNode[edge.dst].push(index);
      if (ARCHITECTURAL_RELS.has(edge.rel)) {
        if (archAdj[edge.src]) uniquePush(archAdj, edge.src, edge.dst);
        if (archAdj[edge.dst]) uniquePush(archAdj, edge.dst, edge.src);
      }
    });

return [...ids].sort((a, b) => {
      const an = byId[a] || {};
      const bn = byId[b] || {};
      return (
        (bn.importance || 0) - (an.importance || 0) ||
        String(an.qualified || an.label || a).localeCompare(String(bn.qualified || bn.label || b)) ||
        a.localeCompare(b)
      );
    });

return [...edgeIndexes].filter((index) => {
      const edge = edges[index];
      return edge && nodeIds.has(edge.src) && nodeIds.has(edge.dst);
    });

return {
        query,
        matchIds: [],
        contextIds: [],
        nodeIds: new Set(),
        edgeIndexes: [],
        totalMatches: 0,
      };

